async function askRealAI(q: string, sw: boolean): Promise<string> {
  try {
    const prompt = encodeURIComponent('Answer ONLY in simple clear English. Use plain text only. Do NOT use ** or markdown or tables. Use short simple sentences, numbered list 1. 2. 3. if needed. You are VIBRA AI from Mombasa. Question: ' + q);
    const res = await fetch('https://text.pollinations.ai/' + prompt);
    let txt = await res.text();
    if (!txt || txt.length < 5) return '';
    txt = txt.replace(/\*\*/g, '').replace(/###/g, '').replace(/##/g, '').replace(/\*/g, '').replace(/\|/g, ' ').replace(/<br>/g, ' ').replace(/---/g, '').replace(/__/g, '').replace(/I am VIBRA AI from Mombasa./g, '').slice(0, 1500);
    if (!sw) return txt;
    let out = '';
    for (let i = 0; i < txt.length; i += 400) {
      const chunk = txt.slice(i, i + 400);
      try {
        const tr = await fetch('https://api.mymemory.translated.net/get?q=' + encodeURIComponent(chunk) + '&langpair=en|sw');
        const j = await tr.json();
        const t = j?.responseData?.translatedText;
        out += (t && t.length > 5 ? t : chunk) + ' ';
      } catch { out += chunk + ' '; }
    }
    return out.trim();
  } catch { return ''; }
}
